.research{color:#1f2937;max-width:1450px;margin:auto}.research h1{font-size:28px;margin:0 0 8px}.research h2{font-size:20px;margin:0 0 16px}.research h3{font-size:16px;margin:18px 0 12px}.research p{line-height:1.55}.research .muted{color:#5b6471;font-size:13px}.research-head,.research-nav,.research-actions{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin-bottom:20px}.research-head{justify-content:space-between}.research a.button,.research button{display:inline-block;text-decoration:none;border:1px solid #d4d9df;background:#fff;border-radius:7px;padding:10px 14px;color:#172a24;font-size:13px;cursor:pointer}.research button.primary,.research a.primary{background:#215847;color:white;border-color:#215847}.research button:disabled{opacity:.5;cursor:not-allowed}.research-nav a{color:#215847;font-weight:700;padding:9px 0}.research-nav a[aria-current=page]{border-bottom:3px solid #215847}.research .notice{padding:14px 17px;border:1px solid #e5c377;background:#fff7e3;border-radius:8px;margin:16px 0}.research .success{background:#edf7ef;border-color:#a7cfb4}.research .cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:18px 0}.research .card,.research .panel{border:1px solid #dce2df;border-radius:10px;background:#fff;padding:18px}.research .card span{display:block;color:#5b6471;font-size:12px;margin-bottom:9px}.research .card strong{font-size:27px}.research .panel{margin:18px 0;min-width:0}.research .table-wrap{overflow:auto}.research table{border-collapse:collapse;width:100%;font-size:13px}.research th,.research td{padding:12px 10px;border:1px solid #d7dfda;text-align:left;vertical-align:top}.research th{background:#edf2ef;font-weight:700}.research td.numeric{text-align:right;font-variant-numeric:tabular-nums}.research .badge{display:inline-block;border-radius:4px;padding:4px 7px;font-size:11px;background:#fff2d3;color:#705118;white-space:nowrap}.research .badge.verified{background:#e2f3e6;color:#215847}.research label{display:block;font-size:13px;font-weight:700;margin-bottom:7px}.research input:not([type=checkbox]),.research select,.research textarea{width:100%;padding:10px;border:1px solid #c4cdc7;border-radius:6px;font:inherit;background:#fff}.research textarea{min-height:120px}.research .fields{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:15px 0}.research .filters{display:flex;gap:14px;align-items:end;flex-wrap:wrap}.research .filters>div{min-width:165px}.research details{margin:16px 0}.research summary{cursor:pointer;font-weight:700}.research pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;padding:12px;background:#f4f6f5}.research .review-layout{display:grid;grid-template-columns:1fr 1fr;gap:20px}.research .path{border-left:3px solid #215847;padding-left:15px;margin:14px 0}.research .copy-text{width:100%;min-height:145px}.research .pagination{margin-top:16px}.research .error-list{color:#9c2820}.research .attestation{display:flex;gap:9px;align-items:start;line-height:1.5;margin:15px 0}.research .attestation input{margin-top:3px}.research button:focus-visible,.research a:focus-visible,.research input:focus-visible,.research select:focus-visible,.research textarea:focus-visible{outline:3px solid #bb922f;outline-offset:2px}@media(max-width:1000px){.research .cards{grid-template-columns:repeat(2,minmax(0,1fr))}.research .review-layout{grid-template-columns:1fr}.research .fields{grid-template-columns:1fr 1fr}}@media(max-width:580px){.research h1{font-size:23px}.research .fields{grid-template-columns:1fr}.research .card,.research .panel{padding:13px}.research-head{align-items:start}}@media print{.sidebar,.skip-link,.research> :not(.chapter){display:none!important}.research .chapter .research-actions,.research .chapter label,.research .chapter textarea{display:none!important}.research .chapter{border:0;padding:0;margin:0}.app-main{margin:0!important;padding:0!important}.page-container{padding:0!important}.app-shell{display:block!important}.research th{print-color-adjust:exact}.research .chapter h2{font-size:16px;font-style:italic;font-weight:400}@page{margin:20mm}}
